// Opt-in city-site renderer. Content, branding and publication policy belong to consumers.
export const escapeHTML = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e = escapeHTML;
export function validateSite(s) {
  for (const field of ['id','name','city','kind','slug','layout','description','heading','emphasis','intro','aboutTitle','about','invitation','invitationText','formatsTitle','monogram']) {
    if (typeof s[field] !== 'string' || !s[field].trim()) throw Error(`Missing ${field}`);
  }
  if (!/^[a-z0-9-]+$/.test(s.id) || !/^[a-z0-9-]+$/.test(s.slug)) throw Error('Unsafe identifier');
  if (!['panorama','editorial','collage','masthead'].includes(s.layout)) throw Error('Unknown layout');
  if (typeof s.publish !== 'boolean') throw Error('Explicit publication policy required');
  if (s.publish && !/^[a-z0-9.-]+\.[a-z]{2,}$/.test(s.domain)) throw Error('Live domain required');
  if (!s.publish && s.domain) throw Error('Unpublished sites must not claim a live domain');
  if (s.calendar && !/^https:\/\/(luma\.com|lu\.ma)\/[a-z0-9_-]+$/.test(s.calendar)) throw Error('Calendar must be an approved Luma URL');
  for (const key of ['ink','accent','paper','highlight']) if (!/^#[\da-f]{6}$/i.test(s.colors?.[key])) throw Error(`Invalid color: ${key}`);
  if (!Array.isArray(s.formats) || !s.formats.length || s.formats.some(f => !f.title || !f.text)) throw Error('Formats required');
  if (!Array.isArray(s.faq) || !s.faq.length || s.faq.some(f => !f.question || !f.answer)) throw Error('FAQ required');
  for (const image of [s.art?.src,s.photo?.src].filter(Boolean)) if (!/^\/assets\/[\w/.-]+$/.test(image) || image.includes('..')) throw Error('Unsafe asset path');
  return s;
}
const arrow = '<svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6" fill="none" stroke="currentColor" stroke-width="1.5"/></svg>';
const email = 'hello@curiouscommons.com';
function head(s, title, description, path='/', noindex=false) {
  const canonical = s.publish ? `https://${s.domain}${path}` : '';
  const schema = { '@context':'https://schema.org', '@type':'WebSite', name:s.name, description:s.description,
    ...(canonical ? {url:`https://${s.domain}/`} : {}), publisher:{'@type':'Organization',name:'Curious Commons',url:'https://curiouscommons.com/'} };
  return `<!doctype html><html lang="en-IN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${e(title)}</title><meta name="description" content="${e(description)}"><meta name="theme-color" content="${s.colors.paper}"><meta name="robots" content="${!s.publish||noindex?'noindex, nofollow':'index, follow'}">${canonical?`<link rel="canonical" href="${canonical}"><meta property="og:url" content="${canonical}">`:''}<meta property="og:type" content="website"><meta property="og:title" content="${e(title)}"><meta property="og:description" content="${e(description)}">${s.publish?`<meta property="og:image" content="https://${s.domain}/assets/brand/social-preview.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="${e(s.name)} by Curious Commons">`:''}<meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/assets/brand/favicon.svg" type="image/svg+xml"><link rel="apple-touch-icon" href="/assets/brand/apple-touch-icon.png"><link rel="preload" href="/assets/fonts/instrument-serif.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/assets/core/site.css"><link rel="stylesheet" href="/assets/brand/theme.css"><script type="application/ld+json">${JSON.stringify(schema).replace(/</g,'\\u003c')}</script></head><body class="layout-${s.layout}"><a class="skip" href="#main">Skip to content</a>${!s.publish?'<div class="draft-banner">Private preview · Not announced or open for registration</div>':''}`;
}
function brand(s) { return s.displayName ? e(s.displayName).replace('AI','<em>AI</em>') : `${e(s.city)} <em>${e(s.kind)}</em>`; }
function nav(s, kit=false) { return `<header class="site-header"><a class="brand" href="/" aria-label="${e(s.name)} home">${brand(s)}</a><nav aria-label="Main navigation">${kit?'<a href="/">Back to home</a>':'<a href="#about">The idea</a><a href="#join">Get involved</a>'}<a class="nav-parent" href="https://curiouscommons.com/">by Curious Commons ${arrow}</a></nav></header>`; }
function footer(s) { return `<footer class="site-footer"><div><a class="brand" href="/">${brand(s)}</a><p>An initiative by <a href="https://curiouscommons.com/">Curious Commons</a>.</p></div><div class="footer-links"><a href="mailto:${email}">Say hello ${arrow}</a>${s.calendar?`<a href="${s.calendar}">Luma calendar ${arrow}</a>`:''}<a href="https://bengalurutechweek.com/2026/">Explore Bengaluru Tech Week 2026 ${arrow}</a></div><p class="footer-note">${e(s.name)} · ${e(s.city)}, India</p></footer></body></html>`; }
function cta(s, secondary=false) { return `<a class="button${secondary?' secondary':''}" href="${s.calendar||`mailto:${email}?subject=${encodeURIComponent(s.name+' updates')}`}">${s.calendar?'Get updates':'Ask about the first edition'} ${arrow}</a>`; }
export function renderHome(config) {
  const s = validateSite(config);
  const heroArt=s.art?`<figure class="hero-art"><img src="${s.art.src}" alt="${e(s.art.alt)}" width="${s.art.width}" height="${s.art.height}" fetchpriority="high" decoding="async"></figure>`:'';
  return head(s,`${s.name} | By Curious Commons`,s.description)+nav(s)+`<main id="main">
  <section class="hero" aria-labelledby="hero-title"><div class="hero-copy"><p class="eyebrow">${e(s.name)} · First edition taking shape</p><h1 id="hero-title">${e(s.heading)}<br><em>${e(s.emphasis)}</em></h1><div class="hero-bottom"><p class="intro">${e(s.intro)}</p><div class="hero-actions">${cta(s)}<a class="text-link" href="#join">Bring an idea ${arrow}</a></div><p class="date-note">Dates and programme to be announced.</p></div></div>${heroArt}${s.layout==='editorial'?`<p class="hero-aside">${e(s.heroAside)}</p>`:''}${s.layout==='masthead'?`<div class="masthead-words" aria-hidden="true">${s.words.map(w=>`<span>${e(w)}</span>`).join('')}</div>`:''}</section>
  <section class="about section-pad" id="about" aria-labelledby="about-title"><p class="eyebrow">The idea</p><div class="about-content"><h2 id="about-title">${e(s.aboutTitle)}</h2><p class="large-copy">${e(s.about)}</p></div></section>
  <section class="formats section-pad" aria-labelledby="formats-title"><div class="section-intro"><p class="eyebrow">What we’re making room for</p><h2 id="formats-title">${e(s.formatsTitle)}</h2><p>These are the conversations we want to start. Confirmed events will be shared as the programme takes shape.</p></div><div class="format-list">${s.formats.map((f,i)=>`<article class="format"><span class="format-number" aria-hidden="true">0${i+1}</span><h3>${e(f.title)}</h3><p>${e(f.text)}</p></article>`).join('')}</div></section>
  ${s.photo?`<section class="commons section-pad" aria-labelledby="commons-title"><figure><img src="${s.photo.src}" alt="${e(s.photo.alt)}" width="1592" height="896" loading="lazy" decoding="async"><figcaption>From Bengaluru Tech Week 2026 · ${e(s.photo.caption)}</figcaption></figure><div><p class="eyebrow">The people behind the week</p><h2 id="commons-title">A Curious<br>Commons initiative.</h2><p>We bring people together around technology and the things they care about. Bengaluru Tech Week is where this story began. ${e(s.city)} will have a character of its own.</p><a class="text-link" href="https://curiouscommons.com/">Meet Curious Commons ${arrow}</a></div></section>`:''}
  <section class="join section-pad" id="join" aria-labelledby="join-title"><div><p class="eyebrow">Help shape the first edition</p><h2 id="join-title">${e(s.invitation)}</h2><p>${e(s.invitationText)}</p><div class="join-actions"><a class="button" href="mailto:${email}?subject=${encodeURIComponent(s.name+' — host or partner')}">Start a conversation ${arrow}</a>${s.calendar?`<a class="text-link" href="${s.calendar}">Follow the calendar ${arrow}</a>`:''}</div></div><div class="faq" aria-label="Useful details">${s.faq.map(f=>`<details><summary>${e(f.question)}<span aria-hidden="true">+</span></summary><p>${e(f.answer)}</p></details>`).join('')}</div></section>
  </main>`+footer(s);
}
export function boilerplate(s) {
  return `${s.name}\nBy Curious Commons\n\n${s.description}\n\n${s.about}\n\nStatus: the first edition is taking shape. Dates, venues, speakers, partners and registration details have not been announced. Do not infer confirmed events from programme ideas.\n\nContact: ${email}\n${s.publish?`Website: https://${s.domain}/\n`:''}${s.calendar?`Updates: ${s.calendar}\n`:''}\nUse the full name ${s.name} on first mention. ${s.monogram} is visual shorthand. The city initiative is organised by Curious Commons. Do not imply government, institutional or third-party event affiliation.\n`;
}
export function renderMediaKit(s, guide=false) {
  validateSite(s);
  const download=`/downloads/${s.slug}-media-kit.zip`;
  const logos=[['wordmark','Primary wordmark','paper'],['mono','One-colour monogram','white'],['reverse','Reverse monogram','dark'],['profile','Profile picture','white']];
  return head(s,`${s.name} — media kit`,`Logos, colours, typography and approved descriptions for ${s.name}.`,guide?'/media-kit/guide/':'/media-kit/',true)+(guide?'':nav(s,true))+`<main id="main" class="kit"><section class="kit-heading"><p class="eyebrow">Curious Commons · Brand resources</p><h1>${e(s.name)}<br><em>Media kit.</em></h1><p>Use these files to introduce the week, credit the organiser, or prepare an approved collaboration.</p>${guide?'':`<div class="kit-downloads"><a class="button" href="${download}" download>Download complete kit ${arrow}</a><a class="text-link" href="/media-kit/brand-guide.pdf" download>Brand guide PDF ↓</a></div>`}</section>
  <section class="kit-section"><div class="kit-section-head"><span class="eyebrow">01 / Identity</span><h2>The name comes first.</h2><p>Use the full event name on first mention. ${e(s.monogram)} is our compact mark, not a replacement for a readable event title. The separate Curious Commons identity identifies the organiser.</p></div><div class="logo-grid">${logos.map(([file,title,bg])=>`<article><div class="logo-preview ${bg}"><img src="/assets/brand/${file}.svg" alt="${e(s.name+' '+title.toLowerCase())}"></div><h3>${title}</h3>${guide?'':`<div class="asset-links"><a href="/assets/brand/${file}.svg" download>SVG ↓</a><a href="/assets/brand/${file}.png" download>PNG ↓</a></div>`}</article>`).join('')}</div></section>
  <section class="kit-section rules"><div><span class="eyebrow">02 / Use with care</span><h2>Give it room.</h2></div><div><p>Leave clear space of at least half a capital letter’s height around the wordmark. Use the supplied artwork: do not stretch, rotate, redraw, add shadows, or place it on a busy image.</p><p>Profile pictures use a pure-white background. Keep all letters inside the circular crop. Use SVG for scalable artwork and the 2048 px profile PNG for social accounts.</p><p>Keep partner marks separate and clearly labelled. A logo in this kit is not permission to announce a partnership. Confirm dates, venues and participants before publishing event material.</p></div></section>
  <section class="kit-section"><span class="eyebrow">03 / Colour & type</span><h2>A consistent character.</h2><div class="swatches">${Object.entries(s.colors).map(([name,hex])=>`<div><span class="swatch" style="background:${hex}"></span><strong>${e(name)}</strong><code>${hex}</code></div>`).join('')}</div><div class="type-pair"><div><h3 class="serif">Instrument Serif</h3><p>Names and short headlines. Regular and supplied artwork; never simulate weight.</p></div><div><h3>Space Grotesk</h3><p>Descriptions, navigation and practical information. Use the included font files and licences.</p></div></div><p>Use dark ink on pale surfaces and white on dark ink. Bright accents are surfaces, not colours for small text. RGB values are digital references. Ask your printer for colour conversion and a physical proof.</p></section>
  <section class="kit-section boilerplate"><span class="eyebrow">04 / Words to use</span><h2>${e(s.name)}</h2><p class="large-copy">${e(s.description)}</p><p>${e(s.about)}</p><p class="status-note">First edition taking shape. Dates and programme to be announced. No speakers, venues or partners are implied by this kit.</p><p>Organised by <a href="https://curiouscommons.com/">Curious Commons</a>. Press and collaboration enquiries: <a href="mailto:${email}">${email}</a>.</p>${guide?'':`<a class="text-link" href="/media-kit/boilerplate.txt" download>Download descriptions ↓</a>`}</section></main>${guide?'</body></html>':footer(s)}`;
}
export function renderNotFound(s) { return head(s,`Page not found | ${s.name}`,'This page could not be found.','/404.html',true)+nav(s,true)+`<main id="main" class="not-found section-pad"><p class="eyebrow">404</p><h1>A different way in.</h1><p>That page isn’t here. Head back to ${e(s.name)}.</p><a class="button" href="/">Back to home ${arrow}</a></main>`+footer(s); }
